INSERT INTO ai_background_task (
    task_id, user_id, tenant_id, session_id, name, task_type, status,
    trigger_config_json, action_prompt, action_agent_id, max_step, run_once,
    next_trigger_at, draft_expires_at, created_at, updated_at
) VALUES (
    #{taskId}, #{userId}, #{tenantId}, #{sessionId}, #{name}, #{taskType}, #{status},
    #{triggerConfigJson}, #{actionPrompt}, #{actionAgentId}, #{maxStep}, #{runOnce},
    #{nextTriggerAt}, #{draftExpiresAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT  FROM ai_background_task
WHERE user_id = #{userId}
  AND (
    task_id = #{taskReference}
    OR task_id LIKE CONCAT(#{taskReference}, '%')
    OR name = #{taskReference}
  )
ORDER BY updated_at DESC
LIMIT 1

SELECT  FROM ai_background_task
WHERE user_id = #{userId}
AND session_id = #{sessionId}
ORDER BY updated_at DESC
LIMIT #{limit}

