INSERT INTO ai_background_task_execution (
    execution_id, task_id, run_id, trigger_reason, status, started_at, created_at, updated_at
) VALUES (
    #{executionId}, #{taskId}, #{runId}, #{triggerReason}, #{status},
    #{startedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, execution_id, task_id, run_id, trigger_reason, status,
       started_at, finished_at, error_message, created_at, updated_at
FROM ai_background_task_execution
WHERE task_id = #{taskId}
ORDER BY created_at DESC
LIMIT #{limit}
